#!/usr/bin/env python3
# SPDX-License-Identifier: MPL-2.0
"""
Minimal policy trainer + C exporter for kiln_nn.

Trains a tiny MLP (discrete actions) with pure Torch, then emits a C header
containing int8 weights, biases, and a KilnNnLayer table ready for
kiln_nn_init().

Replace the toy supervised loop with a real PufferLib / CleanRL / PPO
training loop when you have a simulation of your Kiln rooms + clip world.
The export format stays identical.

Usage:
  python tools/nn/train_export.py --obs 16 --hidden 32 --actions 5 --out policy_chase
"""

from __future__ import annotations

import argparse
from pathlib import Path

import numpy as np
import torch
import torch.nn as nn
import torch.nn.functional as F


class TinyPolicy(nn.Module):
    def __init__(self, obs_dim: int, hidden: int, n_actions: int):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(obs_dim, hidden),
            nn.ReLU(),
            nn.Linear(hidden, hidden),
            nn.ReLU(),
            nn.Linear(hidden, n_actions),
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.net(x)


def quantize_layer(weight: np.ndarray, bias: np.ndarray | None):
    """Symmetric per-tensor quant → int8 + power-of-two scale shift."""
    max_abs = float(np.max(np.abs(weight)))
    if max_abs < 1e-8:
        max_abs = 1.0

    scale = max_abs / 127.0
    shift = int(np.ceil(np.log2(scale))) if scale > 0 else 0
    shift = max(0, min(shift, 15))
    real_scale = 2.0 ** shift

    w_q = np.clip(np.round(weight / real_scale), -128, 127).astype(np.int8)
    b_q = None
    if bias is not None:
        b_q = np.round(bias / real_scale).astype(np.int32)
    return w_q, b_q, shift


def emit_c_header(path: Path, name: str, layers: list[dict],
                  obs_dim: int, action_dim: int):
    max_w = max(max(l["in"], l["out"]) for l in layers)
    lines = [
        "/* Auto-generated by tools/nn/train_export.py — do not edit by hand */",
        f"#ifndef {name.upper()}_NN_H",
        f"#define {name.upper()}_NN_H",
        "",
        '#include "kiln_nn.h"',
        "",
    ]

    for i, L in enumerate(layers):
        w = L["w_i8"]
        lines.append(f"static const int8_t {name}_w{i}[] = {{")
        # Pretty-print in rows of 16
        flat = w.flatten()
        for row in range(0, len(flat), 16):
            chunk = flat[row:row+16]
            lines.append("    " + ", ".join(f"{int(x):4d}" for x in chunk) + ",")
        lines.append("};")
        if L["b_i32"] is not None:
            lines.append(f"static const int32_t {name}_b{i}[] = {{")
            lines.append("    " + ", ".join(str(int(x)) for x in L["b_i32"]) + ",")
            lines.append("};")
        lines.append("")

    lines.append(f"static const KilnNnLayer {name}_layers[] = {{")
    for i, L in enumerate(layers):
        act = "KILN_NN_ACT_RELU" if i < len(layers) - 1 else "KILN_NN_ACT_LINEAR"
        bias_ptr = f"{name}_b{i}" if L["b_i32"] is not None else "NULL"
        lines.append(
            "    {"
            f".in_features = {L['in']}, "
            f".out_features = {L['out']}, "
            f".act = {act}, "
            f".weights_i8 = {name}_w{i}, "
            f".bias_i32 = {bias_ptr}, "
            f".scale_shift = {L['shift']}, "
            ".weights_f32 = NULL, .bias_f32 = NULL"
            "},"
        )
    lines.append("};")
    lines.append("")
    lines.append("/*")
    lines.append(" * Usage:")
    lines.append(f" *   static uint8_t scratch[kiln_nn_scratch_bytes({max_w}, {len(layers)})];")
    lines.append(" *   KilnNnModel model;")
    lines.append(f" *   kiln_nn_init(&model, KILN_NN_DTYPE_INT8, {len(layers)},")
    lines.append(f" *              {name}_layers, {obs_dim}, {action_dim},")
    lines.append(" *              NULL, scratch, sizeof(scratch));")
    lines.append(" */")
    lines.append(f"#endif /* {name.upper()}_NN_H */")
    path.write_text("\n".join(lines) + "\n")
    print(f"Wrote {path}")


def main():
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("--obs", type=int, default=16)
    ap.add_argument("--hidden", type=int, default=32)
    ap.add_argument("--actions", type=int, default=5)
    ap.add_argument("--steps", type=int, default=2000)
    ap.add_argument("--out", type=str, default="policy")
    args = ap.parse_args()

    torch.manual_seed(0)
    model = TinyPolicy(args.obs, args.hidden, args.actions)
    opt = torch.optim.Adam(model.parameters(), lr=1e-3)

    # Toy supervised target — replace with real RL (PufferLib / PPO)
    for step in range(args.steps):
        obs = torch.randn(64, args.obs)
        target = (obs[:, 0] > 0).long() % args.actions
        logits = model(obs)
        loss = F.cross_entropy(logits, target)
        opt.zero_grad()
        loss.backward()
        opt.step()
        if step % 500 == 0:
            print(f"step {step:4d}: loss={loss.item():.4f}")

    layers = []
    with torch.no_grad():
        linears = [m for m in model.net if isinstance(m, nn.Linear)]
        for lin in linears:
            w = lin.weight.cpu().numpy()
            b = lin.bias.cpu().numpy() if lin.bias is not None else None
            w_q, b_q, shift = quantize_layer(w, b)
            layers.append({
                "in": w.shape[1],
                "out": w.shape[0],
                "w_i8": w_q,
                "b_i32": b_q,
                "shift": shift,
            })

    out_path = Path(args.out)
    out_path.parent.mkdir(parents=True, exist_ok=True)
    emit_c_header(Path(f"{args.out}.h"), out_path.name, layers,
                  args.obs, args.actions)

    # Golden vector for host/console self-tests
    obs = torch.randn(1, args.obs)
    with torch.no_grad():
        logits = model(obs).numpy().ravel()
    np.savez(f"{args.out}_golden.npz",
             obs=obs.numpy().ravel(),
             logits=logits,
             obs_dim=args.obs,
             action_dim=args.actions)
    print(f"Wrote {args.out}_golden.npz")


if __name__ == "__main__":
    main()
